    public static function getLogo(string $clientName): ?string
    {
        return self::$logos[$clientName]['svg'] ?? null;
    }

    public static function getViewBox(string $clientName): ?string
    {
        return self::$logos[$clientName]['viewBox'] ?? null;
    }

    public static function hasLogo(string $clientName): bool
    {
        return isset(self::$logos[$clientName]);
    }

    public static function getClientNames(): array
    {
        return array_keys(self::$logos);
    }
